// Duas generated by scripts/convert-doaa.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import type { ZikrCategory } from "@/lib/data";

export type Doaa = { title: string; titleEn?: string; items: ZikrCategory["items"] };
export type DoaaCategory = { id: string; title: string; icon: string; prayers: Doaa[] };

export const getDoaaCategories = cache(
  async (): Promise<DoaaCategory[]> =>
    JSON.parse(await fs.readFile(path.join(process.cwd(), "data/doaa/categories.json"), "utf8")),
);
